93:    /** The sheet's figures now; empty when the sheet does not exist. */
94:    public Snapshot snapshot(String sheetId) {
95:        Sheet sheet = sheets.findById(sheetId).orElse(null);
96:        LocalDate today = sheet == null ? null : sheet.getToday();
97:        List<List<Rate>> sheetRates = rateChain(sheetId);
98:        Map<Long, List<Claim>> counted = new LinkedHashMap<>();
99:        for (Claim claim : claims.findBySheetIdOrderByIdDesc(sheetId)) {
100:            if (claim.getStatus().counts()) {
101:                counted.computeIfAbsent(claim.getPersonId(), id -> new ArrayList<>()).add(claim);
102:            }
