299:            parent[i] = i;
300:            for (String name : members.get(i).names()) {
301:                Integer other = firstWith.putIfAbsent(name, i);
302:                if (other != null) {
303:                    int a = top(parent, i);
304:                    int b = top(parent, other);
305:                    if (a != b) {
